recipes.code:
{
  "inputs": [
    {
      "id": "nevent-jwt-token",
      "type": "promptString",
      "description": "Nevent JWT access token for authenticating with the Nevent API",
      "password": true
    }
  ],
  "servers": {
    "nevent": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "mcp-nevent@1.7.1"
      ],
      "env": {
        "NEVENT_JWT_TOKEN": "${input:nevent-jwt-token}",
        "NEVENT_OPERATION_MODE": "READ_ONLY"
      }
    }
  }
}
